import logging
import re
import urllib


class SwVersion(object):
    """ Represents BTS software version """

    API_KEY = {
        'ESPOO1': 'cmVmdGtuOjAxOjE4MjQ4ODU3MTE6UUlkbmU0REZkZDZtd0xVMElYY3ZQZTQ3TXkz',
        'ESPOO2': 'AKCp8oiHU5YPce4g24nY4H9XxoVHAVzcydFrggjst4Ym8FPW7jnEnLDyTDbkNk6ma5XV2NC95',
        'ESPOO3': 'cmVmdGtuOjAxOjE4Mjg2MDk4OTA6Wm5xQ2llcUVtc0xDaXFnTVpyMmNCRmVyZXdl',
        'HZ1': 'AKCp8oiHU5YVmxybvkJef917wNemeaeHb5LMqX8272B2AU1dcGx4fHim1ifQ8JVJcZR6kZYMj'
    }

    __MISSING_IMPLEMENTATION_ERROR_MSG = '{} class has no implementation of {} attribute'
    _bts_type = None

    def __init__(self, raw, url=None):
        self._raw = raw
        self._nominal = None
        self._simplified = None
        self._package = None
        self._url = url
        self._size = None

    def __repr__(self):
        return "{}('{}')".format(self.__class__.__name__, self.raw)

    @classmethod
    def from_nominal(cls, nominal):
        """
        Alternative constructor allowing SwVersion class instance based on nominal software version definition
        """
        raise NotImplementedError(
            cls.__MISSING_IMPLEMENTATION_ERROR_MSG.format(cls.__name__, 'package'))

    @property
    def raw(self):
        """
        Returns SW version in raw format, i.e. '5G21A_GNB_0011_000800_000315'

        :rtype: str
        """
        return self._raw

    @property
    def nominal(self):
        """
        Returns SW version in nominal format, i.e. '5G21A_11.800.315'

        :rtype: str
        """
        if self._nominal is None:
            parts = [part.lstrip('0') for part in self._raw.split('_')]
            parts[-3] = '0' if parts[-3] == '' else parts[-3]
            self._nominal = parts[0] + '_' + '.'.join(parts[-3:])
        return self._nominal

    @property
    def simplified(self):
        """
        Returns SW version in simplified format, i.e. '11.800.315'

        :rtype: str
        """
        if self._simplified is None:
            self._simplified = self.nominal.split('_')[1]
        return self._simplified

    def get_package(self):
        """
        Returns SW version in package name format, i.e. 'AirScale-11.800.315.zip'

        :rtype: str
        """
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__, 'package'))

    @property
    def url(self):
        """
        Returns the URL of the software package.
        The URL is dynamically generated based on the software version details. If the `_url` attribute is already set,
        it is returned directly. Otherwise, the URL is constructed using the specific logic defined for the software
        version.
        Example:
            self._url is not None:
                Returns URL only for get proper api_key:
            'https://artifactory-espoo1.ext.net.nokia.com:443/artifactory/mnpute-rotta-local/BSR/'

            self._url is None:
                Returns SW version in URL format, i.e.
            'https://artifactory-espoo1.int.net.nokia.com/artifactory/System_Release/11.800.315/AirScale-11.800.315.zip'
        """
        if self._url is not None:
            return self._url
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__, 'url'))

    @property
    def api_key(self):
        for arti_location in self.API_KEY:
            if arti_location.lower() in self.url.lower():
                return self.API_KEY[arti_location]
        else:
            raise NotImplementedError("API_KEY for url {} not defined".format(self.url))

    @property
    def with_t1_suffix(self):
        """
        Returns SwVersion instance with same raw number but with added T1 suffix (if not present already).

        :rtype: SwVersion
        """
        if self.has_t1_suffix:
            return self
        elif self.has_t2_suffix:
            return self.__class__(raw=self.raw.replace('T2', 'T1'))
        else:
            return self.__class__(raw='{}T1'.format(self.raw))

    @property
    def with_t2_suffix(self):
        """
        Returns SwVersion instance with same raw number but with added T2 suffix (if not present already).

        :rtype: SwVersion
        """
        if self.has_t2_suffix:
            return self
        elif self.has_t1_suffix:
            return self.__class__(raw=self.raw.replace('T1', 'T2'))
        else:
            return self.__class__(raw='{}T2'.format(self.raw))

    @property
    def without_t_suffix(self):
        """
        Returns SwVersion instance with same raw number but without T1 nor T2 suffix (if present).

        :rtype: SwVersion
        """
        return self.__class__(raw=self.raw[:-2]) if self.has_t1_suffix or self.has_t2_suffix else self

    @property
    def has_t1_suffix(self):
        """
        Returns True if SW version has T1 suffix, False otherwise.

        :rtype: bool
        """
        return self.raw.endswith('T1')

    @property
    def has_t2_suffix(self):
        """
        Returns True if SW version has T2 suffix, False otherwise.

        :rtype: bool
        """
        return self.raw.endswith('T2')

    @property
    def size(self):
        """
        Returns size of SW version (in bytes) read from remote repository.

        :rtype: int
        """
        if self._size is None:
            self._size = int(urllib.urlopen(self.url).info().getheader('content-length'))
        return self._size


class GnbSwVersion(SwVersion):
    """ Represents 5G BTS software version """

    _bts_type = 'GNB'

    def get_package(self):
        """
        Returns SW version in package name format, i.e. 'AirScale-11.800.315.zip'

        :rtype: str
        """
        if self._package is None:
            self._package = 'AirScale-{}.zip'.format(self.simplified)
        return self._package

    @property
    def url(self):
        """
        Returns SW version in URL format, i.e.
        'https://artifactory-espoo1.int.net.nokia.com/artifactory/System_Release/11.800.315/AirScale-11.800.315.zip'

        :rtype: str
        """
        if self._url is None:
            self._url = 'https://artifactory-espoo1.int.net.nokia.com/artifactory/mnp5g-central-public-local/' \
                        'System_Release/{}/{}'.format(self.without_t_suffix.simplified, self.get_package())
        return self._url

    @classmethod
    def from_nominal(cls, nominal):
        """
        Alternative constructor allowing creation GnbSwVersion class instance based on nominal software
        version definition
        """
        branch, streamline, version = nominal.split('.')
        raw = '_'.join([branch.split('_')[0],
                        cls._bts_type,
                        branch.split('_')[1].zfill(4),
                        streamline.zfill(6),
                        version.zfill(6)])
        return cls(raw)


class SbtsSwVersion(SwVersion):
    """ Represents SBTS software version. Variable __sbts_branches needs to be update with each SBTS release"""

    _bts_type = 'ENB'
    __sbts_trunk = 'SBTS00'
    _re_trunk_bti = re.compile(r'9\d{3}')  # '9999', '9990' etc

    def __ge__(self, other):
        release, bti, major, minor = self.nominal.split('.')
        minor = re.search(r'(?P<MINOR_NUMBER>\d+)', minor).group('MINOR_NUMBER')
        release = release.replace('00', '99')
        other_release, other_bti, other_major, other_minor = other.nominal.split('.')
        other_minor = re.search(r'(?P<MINOR_NUMBER>\d+)', other_minor).group('MINOR_NUMBER')
        other_release = other_release.replace('00', '99')

        values = [release.lower(), int(bti), int(major), int(minor)]
        other_values = [other_release.lower(), int(other_bti), int(other_major), int(other_minor)]

        if bti != other_bti and not self.is_trunk_build() and not other.is_trunk_build():
            raise ValueError("Cannot compare build with different BranchTypeIdentifier")

        if self.bts_type != other.bts_type:
            raise ValueError("Cannot compare build with different bts type: [{} vs {}]".format(self.bts_type,
                                                                                               other.bts_type))
        start_index = 0

        if self.is_trunk_build() and other.is_trunk_build():
            start_index = 2

        for index, value in enumerate(values[start_index:], start_index):
            if values[index] > other_values[index]:
                return True
            elif values[index] < other_values[index]:
                return False

        if minor == other_minor:
            return True
        return False

    def __eq__(self, other):
        def replace_release_to_trunk(build):
            build_splited = build.split('_')
            build_splited[0] = self.__sbts_trunk
            return '_'.join(build_splited)

        if not isinstance(other, SbtsSwVersion):
            return False

        l_raw = self.raw
        r_raw = other.raw
        if self.is_trunk_build():
            l_raw = replace_release_to_trunk(self.raw)
        if other.is_trunk_build():
            r_raw = replace_release_to_trunk(other.raw)

        if l_raw == r_raw:
            return True
        return False

    def __ne__(self, other):
        return not self.__eq__(other)

    @property
    def bts_type(self):
        return self._bts_type

    @property
    def release(self):
        """
        Returns release of given software, in case of trunk it will be SBTS00
        :rtype: str
        """
        return self.get_release(use_default_for_trunk=True)

    @property
    def simplified(self):
        """
        Returns SW version in simplified format, i.e. '11.800.315'

        :rtype: str
        """
        if self._simplified is None:
            self._simplified = '.'.join(self.nominal.split('.')[1:])
        return self._simplified

    def get_release(self, use_default_for_trunk=True):
        """
        Returns release of given software, in case of trunk it will be SBTS00
        :param use_default_for_trunk: If True trunk release will be returned as SBTS00, otherwise as it is in raw

        :rtype: str
        """
        release = self.nominal.split('.')[0]
        if use_default_for_trunk and self.is_trunk_build():
            return self.__sbts_trunk
        return release

    def get_previous_release(self, level='n1'):
        """
        Returns the previous release based on the given level.

        :param level: The level of the previous release, n0, n1, n2 ETC Default is 'n1'.
        :type level: str
        :return: The previous release.
        :rtype: str
        """
        number_of_previous_releases = int(level[1:])
        raw_release = self.nominal.split('.')[0]
        year, year_release = re.search(r'SBTS(\d+)R(\d+)', raw_release).groups()
        target_year = int(year)
        target_year_release = int(year_release) - number_of_previous_releases

        while target_year_release <= 0:
            target_year = target_year - 1
            number_of_releases_in_year = self._get_number_of_releases(target_year)
            target_year_release = number_of_releases_in_year - abs(target_year_release)

        target_release = 'SBTS{}R{}'.format(target_year, target_year_release)
        return target_release

    @staticmethod
    def _get_number_of_releases(release):
        if (isinstance(release, int) and release < 24) or (not isinstance(release, int) and release < 'SBTS24R1'):
            return 4
        else:
            return 3

    def is_trunk_build(self):
        branch_type_identifier = self.nominal.split('.')[1]
        if SbtsSwVersion._re_trunk_bti.search(branch_type_identifier):
            return True
        return False

    def get_package(self, package_variant='A54'):
        """
        Returns SW version in package name format, i.e.
        'SBTS00_ENB_9999_210318_000011_release_BTSSM_downloadable_A54.zip'

        :rtype: str
        """
        if self._package is None:
            head, mid, tail = self.simplified.split('.')
            test = ''

            if self.raw.endswith('T1'):
                tail = tail.replace('T1', '')
                test = '_testpackage_T1'
            elif self.raw.endswith('T2'):
                tail = tail.replace('T2', '')
                test = '_testpackage_T2'

            tail = tail.zfill(6)

            if package_variant:
                package_variant = '_{}'.format(package_variant)
            else:
                package_variant = ''
            self._package = '{}_{}_{}_{}_{}_release_BTSSM_downloadable{}{}.zip'.format(self.release,
                                                                                       self._bts_type,
                                                                                       head, mid, tail, test,
                                                                                       package_variant)
        return self._package

    @property
    def url(self, package_variant='A54'):
        """
        Returns SW version in URL format, i.e.
        In case of trunk release:
        'https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/build/ \
         SBTS00/SBTS00_ENB_9999_230329_000007/SBTS00_ENB_9999_230329_000007_release_BTSSM_downloadable_A54.zip'

        :rtype: str
        """

        if self._url is None:
            self._url = 'https://artifactory-espoo2.int.net.nokia.com/artifactory/mn-cosi-sran-central-public-local/' \
                        'build/{}/{}/{}'.format(self.release, self.raw_with_release,
                                                self.get_package(package_variant=package_variant))
        return self._url

    @property
    def nominal(self):
        """
        Returns SW version in nominal format, i.e. '5G21A_11.800.315'

        :rtype: str
        """
        if self._nominal is None:
            release, hw, bti, major, minor = self._raw.split('_')
            self._nominal = '.'.join([release, bti, major, minor])
        return self._nominal

    @property
    def raw_with_release(self):
        """
        Returns raw version of sw string with SBTS00 on trunk and proper prefix for branches

        :rtype: str
        """
        return '{}_{}'.format(self.release, '_'.join(self.raw.split('_')[1:]))


class Fsm3SwVersion(SbtsSwVersion):
    """ Represents FSM3 software version. Variable __sbts_branches needs to be update with each SBTS release"""

    _bts_type = 'FSM3'

    @property
    def url(self, package_variant='A54'):
        """
        Returns SW version in URL format, i.e.
        In case of trunk release:
        'https://lterel.es-si-s3-z4.eecloud.nsn-net.net/build/
        SBTS00_FSM3/SBTS00_FSM3_9999_221219_000003_release_BTSSM_downloadable_A54.zip'
        'https://lterel.es-si-s3-z2.eecloud.nsn-net.net/build/
        SBTS23R1_FSM3/SBTS23R1_FSM3_0000_000084_000000_release_BTSSM_downloadable_A54.zip'
        :rtype: str
        """

        if self._url is None:
            self._url = 'https://lterel.es-si-s3-z4.eecloud.nsn-net.net/build/{}_FSM3/{}'.format(
                self.release, self.get_package(package_variant))
        return self._url


class IRUSwVersion(SbtsSwVersion):
    """
    Represents (Independent RU) RUSW software version.
    Variable __sbts_branches needs to be update with each SBTS release
    """

    _bts_type = 'RUSW'

    def get_package(self):
        """
        Returns SW version in package name format, i.e.
        'RUSW_AVQJ_000006_476722A-476723A-476724A.zip'

        :rtype: str
        """
        if self._package is None:
            self._package = '_'.join([self._raw]) + '.zip'
        return self._package

    @property
    def url(self):
        """
        Returns SW version in URL format, i.e.
        'https://artifactory-mn-espoo3.int.net.nokia.com/artifactory/mn-rusw-local/build/RUSW
        /RUSW_AVQJ_000006/RUSW_AVQJ_000006_476722A-476723A-476724A.zip'

        :rtype: str
        """
        if self._url is None:
            self._url = 'https://artifactory-mn-espoo3.int.net.nokia.com/artifactory/mn-rusw-local/build/' \
                        '{}/{}/{}'.format(self.release, self.component_name_and_version, self.get_package())
        return self._url

    @property
    def nominal(self):
        """
        Returns SW version in nominal format, i.e. 'RUSW.AVQJ.000006.476722A-476723A-476724A'

        :rtype: str
        """
        if self._nominal is None:
            component, name, version, details = self._raw.split('_')
            self._nominal = '.'.join([component, name, version, details])
        return self._nominal

    @property
    def component_name_and_version(self):
        """
        Returns SW version in component_name_version format, i.e. 'RUSW_AVQJ_000006'

        :rtype: str
        """
        component, name, version, details = self._raw.split('_')
        return '_'.join([component, name, version])


class SwVersionFactory(object):
    """ Creates SwVersion instances. """

    @classmethod
    def create_sw_version(cls, raw_sw_version):
        """
        Creates SwVersion with given raw number.

        :param raw_sw_version: raw SW version number, i.e. '5G21A_GNB_0011_000800_000315'
        :type raw_sw_version: str
        :return: SwVersion instance
        :rtype: SwVersion
        """
        if not RawSwValidator.any(raw_sw_version):
            raise ValueError("Given software version does not match any of supported builds")
        if RawSwValidator.fsm3(raw_sw_version):
            logging.info('Creating Fsm3SwVersion {}'.format(raw_sw_version))
            return Fsm3SwVersion(raw=raw_sw_version)
        elif RawSwValidator.gnb(raw_sw_version):
            logging.info('Creating GnbSwVersion {}'.format(raw_sw_version))
            return GnbSwVersion(raw=raw_sw_version)
        elif RawSwValidator.sbts(raw_sw_version):
            logging.info('Creating SbtsSwVersion {}'.format(raw_sw_version))
            return SbtsSwVersion(raw=raw_sw_version)
        elif RawSwValidator.rusw(raw_sw_version):
            logging.info('Creating IRUSwVersion {}'.format(raw_sw_version))
            return IRUSwVersion(raw=raw_sw_version)

    @classmethod
    def create_sw_version_from_nominal(cls, nominal_sw_version):
        """
        Creates SwVersion with given nominal string
        NOTE: in case of SBTS releases nominal is same as raw
        :param nominal_sw_version: raw SW version number, i.e. '5G21A_GNB_0011_000800_000315'
        :type nominal_sw_version: str
        :return: SwVersion instance
        :rtype: SwVersion
        """
        if not RawSwValidator.any(nominal_sw_version):
            raise ValueError("Given software version does not match any of supported builds")
        if RawSwValidator.gnb(nominal_sw_version):
            logging.info('Creating GnbSwVersion {}'.format(nominal_sw_version))
            return GnbSwVersion.from_nominal(nominal=nominal_sw_version)
        elif RawSwValidator.sbts(nominal_sw_version):
            logging.info('Creating SbtsSwVersion {}'.format(nominal_sw_version))
            return SbtsSwVersion(raw=nominal_sw_version)


class RawSwValidator(object):
    """ Validates raw software version strings """

    @classmethod
    def sbts(cls, raw_sw_version):
        """
        Validate if given raw sw string is in correct format for SBTS
        :param raw_sw_version: eg: SBTS00_ENB_9999_210318_000011
        :return: bool
        """
        return raw_sw_version.startswith('SBTS')

    @classmethod
    def gnb(cls, raw_sw_version):
        """
        Validate if given raw sw string is in correct format for 5G
        :param raw_sw_version: eg: 5G21A_GNB_0011_000800_000315
        :return: bool
        """
        return raw_sw_version.startswith('5G')

    @classmethod
    def fsm3(cls, raw_sw_version):
        """
                Validate if given raw sw string is in correct format for 5G
                :param raw_sw_version: eg: SBTS23R1_FSM3_0000_000084_000000, SBTS00_FSM3_9999_221213_000002
                :return: bool
                """
        return True if 'FSM3' in raw_sw_version else False

    @classmethod
    def rusw(cls, raw_sw_version):
        """
        Validate if given raw sw string is in correct format for 5G
        :param raw_sw_version: eg: RUSW_AVQJ_000006_476722A-476723A-476724A
        :return: bool
        """
        return True if 'RUSW' in raw_sw_version else False

    @classmethod
    def any(cls, raw_sw_version):
        """
        Check if given raw sw string matches any of the supported software formats
        :param raw_sw_version:
        :return: bool
        """
        validators = (cls.sbts, cls.gnb, cls.fsm3, cls.rusw)
        return any(validator(raw_sw_version) for validator in validators)
